import sys

def is_substring(a, b):
    return a in b

def can_reorder(strings):
    strings.sort(key=lambda x: (len(x), x))
    for i in range(len(strings) - 1):
        if not is_substring(strings[i], strings[i + 1]):
            return False
    return True

def main():
    import sys
    input = sys.stdin.read().splitlines()
    n = int(input[0])
    strings = input[1:]
    if can_reorder(strings):
        print("YES")
        for s in strings:
            print(s)
    else:
        print("NO")

main()
